const initWishlist = () => {
    const buttons = document.querySelectorAll('[data-wishlist-button]');

    if (!buttons.length || !window.wooshopWishlist) {
        return;
    }

    buttons.forEach((button) => {
        button.addEventListener('click', async () => {
            if (button.disabled) {
                return;
            }

            const productId = button.dataset.productId;

            if (!productId) {
                return;
            }

            button.disabled = true;

            const formData = new FormData();

            formData.append('action', 'wooshop_toggle_wishlist');

            formData.append('product_id', productId);

            formData.append('nonce', window.wooshopWishlist.nonce);

            try {
                const response = await fetch(window.wooshopWishlist.ajaxUrl, {
                    method: 'POST', credentials: 'same-origin', body: formData,
                });

                const result = await response.json();

                if (!result.success) {
                    throw new Error(result.data?.message || 'Wishlist update failed.');
                }

                const isAdded = result.data.added;

                button.setAttribute('aria-pressed', isAdded ? 'true' : 'false');

                const text = button.querySelector('.wishlist-button__text');

                if (text) {
                    text.textContent = isAdded ? 'Remove from wishlist' : 'Add to wishlist';
                }

                const countElements = document.querySelectorAll('.wishlist-count');

                countElements.forEach((element) => {
                    element.textContent = result.data.count;
                });

            } catch (error) {
                console.error('Wishlist error:', error);
            } finally {
                button.disabled = false;
            }
        });
    });
};

export default initWishlist;